static kal_uint32 return_sensor_id(void)
{
	return ((read_cmos_sensor_byte(0x0000) << 8) | read_cmos_sensor_byte(0x0001));
}

#define EEPROM_IIC_ADDR 0xA6
#define IDENTIFIER_REGISTER_ADDR  0x0001
#define IDENTIFIER_REGISTER_VALUE 0x50

static kal_uint16 read_cmos_eeprom_byte(kal_uint16 addr)
{
	kal_uint16 get_byte = 0;
	char pu_send_cmd[2] = {(char)(addr >> 8), (char)(addr & 0xFF)};
	iReadRegI2C(pu_send_cmd, 2, (u8*)&get_byte, 1, EEPROM_IIC_ADDR);
	return get_byte;
}

static kal_uint32 get_imgsensor_id(UINT32 *sensor_id)
{
	kal_uint8 i = 0;
	kal_uint8 retry = 5;
	kal_uint16 GMSFlags = 0;	
	

	LOG_INF("[%s] +", __func__);

	while (imgsensor_info.i2c_addr_table[i] != 0xff)
	{
		spin_lock(&imgsensor_drv_lock);
		imgsensor.i2c_write_id = imgsensor_info.i2c_addr_table[i];
		spin_unlock(&imgsensor_drv_lock);
		do
		{
			GMSFlags = read_cmos_eeprom_byte(IDENTIFIER_REGISTER_ADDR);
			printk("no gms flag = 0x%x\n", GMSFlags);
			*sensor_id = return_sensor_id();
			//if ((*sensor_id == imgsensor_info.sensor_id) && (GMSFlags == IDENTIFIER_REGISTER_VALUE)){
			if (*sensor_id == imgsensor_info.sensor_id){
				LOG_INF("hct gzc i2c write id: 0x%x, ReadOut sensor id: 0x%x, imgsensor_info.sensor_id:0x%x.\n", imgsensor.i2c_write_id, *sensor_id, imgsensor_info.sensor_id);

				return ERROR_NONE;
			}
			LOG_INF("hct gzc Read sensor id fail, i2c write id: 0x%x, ReadOut sensor id: 0x%x, imgsensor_info.sensor_id:0x%x.\n", imgsensor.i2c_write_id, *sensor_id, imgsensor_info.sensor_id);
			retry--;
		} while (retry > 0);
		i++;
		retry = 2;
	}

	if ((*sensor_id != imgsensor_info.sensor_id) || (GMSFlags != IDENTIFIER_REGISTER_VALUE))
	{
		*sensor_id = 0xFFFFFFFF;
		LOG_INF("[%s] -error-", __func__);
		return ERROR_SENSOR_CONNECT_FAIL;
	}
	LOG_INF("[%s] -", __func__);
	return ERROR_NONE;
}

static kal_uint32 open(void)
{
	kal_uint8 i = 0;
	kal_uint8 retry = 5;
	kal_uint32 sensor_id = 0;
	LOG_INF("[%s] ", __func__);
	//LOG_1;
	while (imgsensor_info.i2c_addr_table[i] != 0xff)
	{
		spin_lock(&imgsensor_drv_lock);
		imgsensor.i2c_write_id = imgsensor_info.i2c_addr_table[i];
		spin_unlock(&imgsensor_drv_lock);
		do
		{
			sensor_id = return_sensor_id();
			if (sensor_id == imgsensor_info.sensor_id)
			{

				LOG_INF("hct gzc open i2c write id: 0x%x, sensor id: 0x%x\n", imgsensor.i2c_write_id, sensor_id);
				break;
			}
			LOG_INF("hct gzc open Read sensor id fail, id: 0x%x, sensor id: 0x%x\n", imgsensor.i2c_write_id, sensor_id);
			retry--;
		} while (retry > 0);
		i++;
		if (sensor_id == imgsensor_info.sensor_id)
			break;
		retry = 2;
	}
	if (imgsensor_info.sensor_id != sensor_id)
	{

		return ERROR_SENSOR_CONNECT_FAIL;
	}
	/* initail sequence write in  */
	LOG_INF("imgsensor init start");
	sensor_init();
	LOG_INF("imgsensor init fin");
	spin_lock(&imgsensor_drv_lock);

	imgsensor.autoflicker_en = KAL_FALSE;
	imgsensor.sensor_mode = IMGSENSOR_MODE_INIT;
	imgsensor.pclk = imgsensor_info.pre.pclk;
	imgsensor.frame_length = imgsensor_info.pre.framelength;
	imgsensor.line_length = imgsensor_info.pre.linelength;
	imgsensor.min_frame_length = imgsensor_info.pre.framelength;
	imgsensor.dummy_pixel = 0;
	imgsensor.dummy_line = 0;
	imgsensor.ihdr_en = KAL_FALSE;
	imgsensor.test_pattern = KAL_FALSE;
	imgsensor.current_fps = imgsensor_info.pre.max_framerate;
	spin_unlock(&imgsensor_drv_lock);

	LOG_INF("[%s] -", __func__);
	return ERROR_NONE;
} 


static kal_uint32 close(void)
{
	LOG_INF("[%s] +", __func__);

	/*No Need to implement this function*/

	LOG_INF("[%s] -", __func__);
	return ERROR_NONE;
}

static kal_uint32 preview(MSDK_SENSOR_EXPOSURE_WINDOW_STRUCT *image_window,
						  MSDK_SENSOR_CONFIG_STRUCT *sensor_config_data)
{
	LOG_INF("E\n");

	spin_lock(&imgsensor_drv_lock);
	imgsensor.sensor_mode = IMGSENSOR_MODE_PREVIEW;
	imgsensor.pclk = imgsensor_info.pre.pclk;
	imgsensor.line_length = imgsensor_info.pre.linelength;
	imgsensor.frame_length = imgsensor_info.pre.framelength;
	imgsensor.min_frame_length = imgsensor_info.pre.framelength;
	imgsensor.autoflicker_en = KAL_FALSE;
	spin_unlock(&imgsensor_drv_lock);
	preview_setting();
	//streaming_control(1);
	set_mirror_flip(imgsensor.mirror);
	mdelay(2);

	return ERROR_NONE;
}
